int main(){
    uint64_t amp = 0;
    uint64_t write_data1 = 0;
    uint64_t write_data2 = 0;
    reset_module();
    init();
	int16_t wave_data[WAVE_LENGTH] = {};
    for (int64_t i = 0; i < WAVE_LENGTH; i++) {
        double angle = (2.0 * M_PI * i) / WAVE_LENGTH;
        wave_data[i] = (int16_t)(i % 0x4000);

        if ( (i >> 2) % 2 == 0) {
            wave_data[i] = 0x0000;
        } else {
            wave_data[i] = 0x0000;
        }
    }
    Xil_Out128(PL_DRAM_ADDR_OFFSET,MAKE128CONST((uint64_t)0x0000, (uint64_t)0x000000003fff3fff));
    Xil_DCacheFlush();
    wave_cache_controller.write_wave_data(0, wave_data, WAVE_LENGTH);

    for (int64_t i = 0; i < WAVE_LENGTH; i++) {
        double angle = (2.0 * M_PI * i) / 1000;
        // wave_data[i] = (int16_t)(0x3fff * sin(angle));
        if (i%4 == 0) {
            wave_data[i] = 0x3fff;
        } else {
            wave_data[i] = 0x0000;
        }
    }
    // wave_cache_controller.write_wave_page_size(47104);
    wave_cache_controller.write_wave_data((WAVE_LENGTH << 1), summed_signal, WAVE_LENGTH);

    for( int i = 0 ; i < 1; i++){
        reset_module();
        wave_cache_controller.reset();
        init();
        delay_coarse(100);
        jb_0.off();
        dds_sw_0.reset();
        dds_sw_0.set_awg();
        dds_sw_1.reset();
        dds_sw_1.set_awg();
        dds_sw_2.reset();
        dds_sw_2.set_awg();
        delay_coarse(1);
        dds_sw_0.on(0);
        dds_sw_1.on(0);
        dds_sw_2.on(0);
        delay_coarse(1000);
        jb_0.on();
        wave_cache_controller.set_awg(0, (WAVE_LENGTH << 1), (37376));
        // delay_coarse(6);
        // wave_cache_controller.set_awg(0, (WAVE_LENGTH << 1), (37376));
        // delay_coarse(6);
        // wave_cache_controller.set_awg(2, (WAVE_LENGTH << 1), (37376));
        // delay(88 * ns);

        delay_coarse(37376);
        jb_0.off();

        auto_start();

        usleep(6000);
    }
}